mapper.sql:
SELECT YYYYMM, SEL_CODE, SITE, 구분, 도우코드, MODEL, EXPEN_SEL, expen_sel명, ACCT_NAME, ITEM_NAME, ITEM_NAME AS SUB_NAME, UNIT_COST, ADJ_YN,
ISNULL([USC_INPUT_QTY],0) AS USC_INPUT_QTY, ISNULL([OUTPUT_A_QTY],0) AS OUTPUT_A_QTY, [USC_INPUT_AMT], (ISNULL([BOH_LINE_WIP_전_QTY],0)+ISNULL([BOH_LINE_WIP_후_QTY],0)+ISNULL([BOH_LINE_FGS_전_QTY],0)+ISNULL([BOH_LINE_FGS_후_QTY],0) +ISNULL([BOH_B_WIP_전_QTY],0)+ISNULL([BOH_B_WIP_후_QTY],0)+ISNULL([BOH_B_FGS_전_QTY],0)+ISNULL([BOH_B_FGS_후_QTY],0)) AS BOH_QTY, (ISNULL([EOH_LINE_WIP_전_QTY],0)+ISNULL([EOH_LINE_WIP_후_QTY],0)+ISNULL([EOH_LINE_FGS_전_QTY],0)+ISNULL([EOH_LINE_FGS_후_QTY],0) +ISNULL([EOH_B_WIP_전_QTY],0)+ISNULL([EOH_B_WIP_후_QTY],0)+ISNULL([EOH_B_FGS_전_QTY],0)+ISNULL([EOH_B_FGS_후_QTY],0)) AS EOH_QTY, (ISNULL([USC_INPUT_QTY],0)+ISNULL([ETCIN_CODE_QTY],0)+ISNULL([ETCIN_RESORT_QTY],0)+ISNULL([ETCIN_REWORK_QTY],0)+ISNULL([ETCIN_SEMI_QTY],0)+ISNULL([ETCIN_ETC_QTY],0)) AS IN_QTY, (ISNULL([OUTPUT_A_QTY],0)+ISNULL([ETCOUT_CODE_전_QTY],0)+ISNULL([ETCOUT_CODE_후_QTY],0)+ISNULL([ETCOUT_SEMI_PAID_전_QTY],0)+ISNULL([ETCOUT_SEMI_PAID_후_QTY],0) +ISNULL([ETCOUT_SEMI_FREE_전_QTY],0)+ISNULL([ETCOUT_SEMI_FREE_후_QTY],0)+ISNULL([ETCOUT_ETC_전_QTY],0)+ISNULL([ETCOUT_ETC_후_QTY],0)) AS OUT_QTY, (ISNULL([LOSS_전_QTY],0)+ISNULL([LOSS_후_QTY],0)) AS LOSS_QTY, CAST(0 AS numeric(18,2)) AS ADJ_QTY, CAST(0 AS numeric(18,2)) AS RMAIN_QTY, ([BOH_LINE_WIP_전_AMT]+[BOH_LINE_WIP_후_AMT]+[BOH_LINE_FGS_전_AMT]+[BOH_LINE_FGS_후_AMT] +[BOH_B_WIP_전_AMT]+[BOH_B_WIP_후_AMT]+[BOH_B_FGS_전_AMT]+[BOH_B_FGS_후_AMT]) AS BOH, ([EOH_LINE_WIP_전_AMT]+[EOH_LINE_WIP_후_AMT]+[EOH_LINE_FGS_전_AMT]+[EOH_LINE_FGS_후_AMT] +[EOH_B_WIP_전_AMT]+[EOH_B_WIP_후_AMT]+[EOH_B_FGS_전_AMT]+[EOH_B_FGS_후_AMT]) AS EOH, ([USC_INPUT_AMT]+[ETCIN_CODE_AMT]+[ETCIN_RESORT_AMT]+[ETCIN_REWORK_AMT]+[ETCIN_SEMI_AMT]+[ETCIN_ETC_AMT]) AS [IN], ([OUTPUT_A_AMT]+[ETCOUT_CODE_전_AMT]+[ETCOUT_CODE_후_AMT]+[ETCOUT_SEMI_PAID_전_AMT]+[ETCOUT_SEMI_PAID_후_AMT] +[ETCOUT_SEMI_FREE_전_AMT]+[ETCOUT_SEMI_FREE_후_AMT]+[ETCOUT_ETC_전_AMT]+[ETCOUT_ETC_후_AMT]) AS [OUT], ([LOSS_전_AMT]+[LOSS_후_AMT]) AS LOSS, CAST(0 AS numeric(18,2)) AS RMAIN_AMT FROM doi_vn_cost WHERE 1=1
and YYYYMM = #{yyyymm}
and SITE = #{site}

mapper.select:
select CASE WHEN ACCT_CLASS='AA' then '가공비' WHEN ACCT_CLASS='CC' then '판매관리비' WHEN ACCT_CLASS='BB' then '개발비' else ACCT_CLASS end as ACCT_CLASS, a.dept, b.dept_name, a.acct, a.EXPEN_SEL, a.EXPEN_SEL명, a.ACCT_NAME, a.ITEM_NAME, sum(a.ACCT_AMT) ACCT_AMT, sum(a.DBT_AMT) as DBT_AMT, sum(a.CRT_AMT) as CRT_AMT from doi_acct_expen a left join (select distinct dept,dept_name from doi_dept where yyyymm=#{yyyymm} and site = #{site}) b on (b.dept=a.dept) where 1=1 and a.EXPEN_SEL not in ('MDAX','MIAX') and a.EXPEN_SEL != 'NONE' --미분류 제외 and a.SEL_CODE = 'ACTUAL'
and a.YYYYMM = #{yyyymm}
and a.SITE = #{site}
and a.ACCT_CLASS = #{costGubun}
AND a.ACCT_CLASS='AA' AND a.EXPEN_SEL NOT IN ('MDAX','MIAX')
AND a.ACCT_CLASS='AA' AND a.EXPEN_SEL IN ('MDAX','MIAX')
group by CASE WHEN ACCT_CLASS='AA' then '가공비' WHEN ACCT_CLASS='CC' then '판매관리비' WHEN ACCT_CLASS='BB' then '개발비' else ACCT_CLASS end , a.dept, b.dept_name, a.acct, a.EXPEN_SEL, a.EXPEN_SEL명, a.ACCT_NAME, a.ITEM_NAME
union all select '재료비', '000', '제조공통', CASE WHEN 재고자산종류='원자재' then '51001010' else '51002010' end, CASE WHEN 재고자산종류='원자재' then 'MDAX' else 'MIDX' end, CASE WHEN 재고자산종류='원자재' then '직접재료비' else '간접재료비' end, '재료비', CASE WHEN 재고자산종류='원자재' then '원재료비' else '부재료비' end, sum(투입금액) 금액,sum(투입금액) CBT_AMT,0 from doi_matl_resc where 1=1
and YYYYMM = #{yyyymm}
and SITE = #{site}
group by 재고자산종류 HAVING sum(투입금액) != 0
order BY 1,2,3,4,5;

select CASE WHEN ACCT_CLASS='AA' THEN '제조비용' WHEN ACCT_CLASS='BB' THEN '개발비' WHEN ACCT_CLASS='CC' THEN '판매관리비' END ACCT_CLASS, EXPEN_SEL, EXPEN_SEL명, ACCT_NAME, ITEM_NAME, DISP_SEQ, SUM(ACCT_AMT) ACCT_AMT from DOI_ACCT_EXPEN where 1=1 and sel_code='ACTUAL'
and YYYYMM = #{yyyymm}
and SITE = #{site}
and expen_sel not in ('MDAX','MIAX') --재료비 제외 GROUP BY YYYYMM,SEL_CODE,SITE,ACCT_NAME,ITEM_NAME,disp_seq,EXPEN_SEL,EXPEN_SEL명,ACCT_CLASS HAVING SUM(ACCT_AMT) != 0 UNION ALL select '제조비용', CASE WHEN 재고자산종류='원자재' then 'MDAX' else 'MIAX' end, CASE WHEN 재고자산종류='원자재' then '직접재료비' else '간접재료비' end, '재료비', CASE WHEN 재고자산종류='원자재' then '원재료비' else '부재료비' end, CASE WHEN 재고자산종류='원자재' then 0 else 0.5 end as disp_seq, sum(투입금액) 금액 --select * from doi_matl_resc where 1=1 and sel_code='ACTUAL'
and YYYYMM = #{yyyymm}
and SITE = #{site}
group by CASE WHEN 재고자산종류='원자재' then 'MDAX' else 'MIAX' end, CASE WHEN 재고자산종류='원자재' then '직접재료비' else '간접재료비' end, CASE WHEN 재고자산종류='원자재' then '원재료비' else '부재료비' end, CASE WHEN 재고자산종류='원자재' then 0 else 0.5 end HAVING sum(투입금액) != 0 order by ACCT_CLASS,DISP_SEQ,EXPEN_SEL,ACCT_NAME,ITEM_NAME;

select.if:
select CASE WHEN a.ACCT_CLASS='AA' then '가공비' WHEN a.ACCT_CLASS='CC' then '판매관리비' WHEN a.ACCT_CLASS='BB' then '개발비' else a.ACCT_CLASS end as ACCT_CLASS , b.DEPT_NAME, EXPEN_SEL, EXPEN_SEL명, ACCT_NAME, ITEM_NAME, SUM(ACCT_AMT) ACCT_AMT from DOI_ACCT_EXPEN a inner join doi_dept b on(a.YYYYMM =b.yyyymm and a.site=b.site and a.dept=b.dept) where 1=1 and a.sel_code='ACTUAL'
and a.YYYYMM = #{yyyymm}
and a.SITE = #{site}
and a.EXPEN_SEL = #{expenSel}
and a.ACCT_NAME = #{acctName}
group by a.YYYYMM, a.SEL_CODE, CASE WHEN a.SITE='HQ' then '본사' WHEN a.site='VN' then 'VINA' else a.SITE end, CASE WHEN a.ACCT_CLASS='AA' then '가공비' WHEN a.ACCT_CLASS='CC' then '판매관리비' WHEN a.ACCT_CLASS='BB' then '개발비' else a.ACCT_CLASS end, b.DEPT_NAME,ACCT_NAME,ITEM_NAME,EXPEN_SEL,EXPEN_SEL명 order by EXPEN_SEL;

select '제조경비' ACCT_CLASS, '제조공통' DEPT_NAME, CASE WHEN 재고자산종류='원자재' then 'MDAX' else 'MIAX' end EXPEN_SEL, CASE WHEN 재고자산종류='원자재' then '직접재료비' else '간접재료비' end EXPEN_SEL명, '재료비' SUB_NAME, CASE WHEN 재고자산종류='원자재' then '원재료비' else '부재료비' end ITEM_NAME, --sum(in_qty) in_qty, sum(투입금액) acct_amt from DOI_MATL_RESC a where 1 = 1
and a.YYYYMM = #{yyyymm}
and a.SITE = #{site}
and CASE WHEN 재고자산종류='원자재' then 'MDAX' else 'MIAX' end = #{expenSel}
group by CASE WHEN 재고자산종류='원자재' then 'MDAX' else 'MIAX' end, CASE WHEN 재고자산종류='원자재' then '직접재료비' else '간접재료비' end, CASE WHEN 재고자산종류='원자재' then '원재료비' else '부재료비' end

mapper.select:
select A.YYYYMM, A.SEL_CODE, A.SITE as SITE, A.구분, A.도우코드 as MODEL, A.도우코드, sum(A.BOH_MONTH) as BOH_MONTH, sum(A.IN_MONTH) as IN_MONTH, sum(A.BONUS_MONTH) as BONUS_MONTH, sum(A.EOH_MONTH) as EOH_MONTH, sum(A.OUT_MONTH) as OUT_MONTH, sum(A.LOSS_MONTH) as LOSS_MONTH, sum(A.NG_MONTH) as NG_MONTH, sum(A.수율제외_MONTH) as 수율제외_MONTH, sum(A.REWORK진행_MONTH) as REWORK진행_MONTH, sum(A.material_loss) as material_loss, sum(COALESCE(B.RMA_OUT,0)) AS RMA_IN
from V_VN_PROD_SUBULV_DOI_PROD_SUBUL A LEFT JOIN DOI_RMA_INOUT B ON (A.YYYYMM=B.YYYYMM and A.SITE=B.SITE and a.도우코드=b.도우코드) where 1=1
and A.YYYYMM = #{yyyymm}
and A.SITE = #{site}
and 구분 = #{prodGubun}
group by A.YYYYMM,A.SEL_CODE,A.SITE,A.구분,A.도우모델,A.도우코드 order by 4,5,6;

select lotrun_no,BOH_MONTH,IN_MONTH,BONUS_MONTH,EOH_MONTH,OUT_MONTH,LOSS_MONTH,NG_MONTH,
수율제외_MONTH,REWORK진행_MONTH,material_loss
from DOI_PROD_LOTRUN
where 1=1

    and YYYYMM = #{yyyymm}


    and SITE = #{site}


    and 구분 = #{prodGubun}


    and 도우코드 = #{modelNType}

order by lotrun_no;

with base_cost as (
select 도우코드 as model, case when expen_sel='MDAX' then '직접재료비' when LEFT(expen_sel,1)='M' then '간접재료비' else '가공비' end c_cost, avg(USC_INPUT_QTY) in_qty, avg((USC_INPUT_QTY + OUTPUT_A_QTY + LOSS_QTY)/ 2.0) as 환산수량, sum(USC_INPUT_AMT) as 투입금액 from ( ) v where 1=1 and expen_sel not in ('NONE') and expen_sel <> '*' group by 도우코드, case when expen_sel='MDAX' then '직접재료비' when LEFT(expen_sel,1)='M' then '간접재료비' else '가공비' end
select model, '가공비' c_cost, avg(in_qty) in_qty, avg(in_qty + OUT_QTY + loss_qty)/ 2 as 환산수량, sum([in]) as 투입금액 from doi_cost where 1=1 and expen_sel not in ('MDAX','MIAX','NONE')
and YYYYMM = #{yyyymm}
and SITE = #{site}
group by model union all select 도우모델 as model, case when mat_class='원자재' then '직접재료비' else '간접재료비' end, avg(in_qty) as in_qty, avg(환산량) as 환산수량, sum(배부금액) as 투입금액 from DOI_MAT_COST where 1=1
and YYYYMM = #{yyyymm}
and SITE = #{site}
group by 도우모델, case when mat_class='원자재' then '직접재료비' else '간접재료비' end
), in_cost as( select model, avg(in_qty) as in_qty, avg(환산수량) as chg_qty, sum(투입금액) as tot_amt, sum(case when c_cost='직접재료비' then 투입금액 else 0 end) d_matcost, sum(case when c_cost='간접재료비' then 투입금액 else 0 end) i_matcost, sum(case when c_cost='가공비' then 투입금액 else 0 end) fab_cost from base_cost group by model ) select model, in_qty, chg_qty, tot_amt, d_matcost, i_matcost, fab_cost, coalesce(d_matcost / nullif(in_qty, 0), 0)+ coalesce(i_matcost / nullif(chg_qty, 0), 0)+ coalesce(fab_cost / nullif(chg_qty, 0), 0) as sum_unitcost, coalesce(d_matcost / nullif(in_qty, 0), 0) dm_unitcost, coalesce(i_matcost / nullif(chg_qty, 0), 0) di_unitcost, coalesce(fab_cost / nullif(chg_qty, 0), 0) f_unitcost from in_cost order by model;

choose.when:
select 구분, 도우코드 AS MODEL, EXPEN_SEL, expen_sel명 AS EXPEN_SEL명, USC_INPUT_QTY AS in_qty, ADJ_QTY AS adj_qty, BOH, USC_INPUT_AMT AS INPUT_AMT, SUB_NAME from ( ) v where SEL_CODE='ACTUAL' and EXPEN_SEL not in ('NONE') and EXPEN_SEL <> '*'
and 도우코드 = #{model}
order by 구분,EXPEN_SEL;

choose.otherwise:
select 구분, MODEL, EXPEN_SEL, EXPEN_SEL명, in_qty, adj_qty, BOH, [IN] INPUT_AMT, SUB_NAME from doi_expen_matl where 1=1 and sel_code='ACTUAL'
and YYYYMM = #{yyyymm}
and SITE = #{site}
and MODEL = #{model}
union all select '공통',도우모델, case when mat_class='원자재' then 'MDAX' else 'MIDX' end as expen_sel, case when mat_class='원자재' then '직접재료비' else '간접재료비' end as expen_sel명, in_qty, 환산량, 0, in_amt, mat_class from doi_mat_cost where 1=1 and sel_code='ACTUAL'
and YYYYMM = #{yyyymm}
and SITE = #{site}
and 도우모델 = #{model}
order by 구분,EXPEN_SEL;

mapper.select:
with BOM as ( select 자재번호,투입단위,자재대분류,row_number() over (partition by 자재번호 order by 자재명) as rn from doi_bom_mast WHERE 1=1
and YYYYMM = #{yyyymm}
and SITE = #{site}
and nullif(자재번호,'') is not null union all select 자재번호,투입단위,품목소분류 ,row_number() over (partition by 자재번호 order by 자재명) as rn from doi_cst_bom WHERE 1=1
and YYYYMM = #{yyyymm}
and SITE = #{site}
) select --a.MAT_CLASS, CASE WHEN a.재고자산종류='원자재' THEN 'MDAX' ELSE 'MIAX' end as expen_sel, CASE WHEN a.재고자산종류='원자재' THEN '직접재료비' ELSE '간접재료비' end as expen_sel명, a.품번 mat_code, a.품명 mat_desc, max(b.자재대분류) mat_lclass, max(b.투입단위) UNIT, SUM(a.투입금액) IN_QTY, AVG(a.최종결산월재고단가) UNIT_COST, SUM(a.투입금액) IN_AMT from DOI_MATL_RESC a left join BOM b on (a.품번 = b.자재번호 and b.rn=1) where 1=1 and a.sel_code = 'ACTUAL'
and a.YYYYMM = #{yyyymm}
and a.SITE = #{site}
group by a.YYYYMM, a.SEL_CODE, a.SITE, a.재고자산종류, a.품번, a.품명 having sum(투입금액) != 0 order by 5,1;

select YYYYMM, SEL_CODE, SITE, 품번, 품명, 규격, 투입금액, 최종결산월재고단가, 투입금액, 자산처리계정, 재고자산종류, FROM DOI_MATL_RESC where 1=1 and sel_code = 'ACTUAL'
and YYYYMM = #{yyyymm}
and SITE = #{site}
and 재고자산종류 = #{matClass}
order by 1,2,3,4;

choose.otherwise:
WITH BOM as ( SELECT * FROM ( select b.yyyymm, b.자재번호, b.자재명, b.자재대분류, row_number() over (partition by b.자재번호 order by (b.자재대분류)) rn1 from doi_bom_mast b where 1=1 and yyyymm = #{yyyymm} and site = #{site} and nullif(자재번호, '') IS NOT NULL union select c.yyyymm, c.자재번호, c.자재명, c.품목대분류, row_number() over (partition by c.자재번호 order by (c.품목대분류)) rn1 --select * from DOI_CST_BOM c where 1=1 and yyyymm = #{yyyymm} and site = #{site} and 품목자산분류 NOT IN ('카세트제품', '제품') and nullif(자재번호, '') IS NOT NULL
)a where rn1=1 ) select a.구분, a.yyyymm, a.sel_code, CASE WHEN a.SITE='HQ' then '본사' WHEN a.site='VN' then 'VINA' end AS SITE, a.도우모델, a.자재번호, b.자재명, case when a.mat_class='원자재' then 'MDAX' else 'MIDX' end as expen_sel, case when a.mat_class='원자재' then '직접재료비' else '간접재료비' end as expen_sel명, a.mat_class, --a.자재대분류, a.in_amt, a.환산량, CASE WHEN 배부방식 IN ('BOM','CST') THEN a.소요량 ELSE NULL END AS 소요량, CASE WHEN 배부방식 = '공통' THEN a.소요량 ELSE NULL END AS 면적, a.사용량 as 배부적수, --소요량 * 환산량 a.배부율, a.배부금액, a.배부방식 from doi_mat_cost a left join bom b on (a.자재번호 = b.자재번호) where 1=1
and A.YYYYMM = #{yyyymm}
and A.SITE = #{site}
and A.SEL_CODE = #{selCode}
order by a.배부방식 desc,a.구분,a.자재번호

select *
from doi_mat_cost
where 1=1

    and YYYYMM = #{yyyymm}


    and SITE = #{site}


    and mat_class = #{matClass}

order by 1,2,3,4,5,6;

select 구분,도우모델, case when a.mat_class='원자재' then 'MDAX' else 'MIDX' end as expen_sel, case when a.mat_class='원자재' then '직접재료비' else '간접재료비' end as expen_sel명, --a.mat_class, sum(배부금액) 배부금액 from doi_mat_cost a where 1=1
and YYYYMM = #{yyyymm}
and SITE = #{site}
and SEL_CODE = #{selCode}
group by 구분,도우모델, case when a.mat_class='원자재' then 'MDAX' else 'MIDX' end, case when a.mat_class='원자재' then '직접재료비' else '간접재료비' end order by 1,2;

select yyyymm, sel_code, site, 도우모델, 자재번호, mat_class, 자재대분류, in_amt, 환산량, 소요량, 배부율, 배부금액, 사용량, CASE WHEN 배부방식='공통' THEN '면적' ELSE 배부방식 END 배부방식 from doi_mat_cost where 1=1
and YYYYMM = #{yyyymm}
and SITE = #{site}
and 도우모델 = #{model}
and 구분 = #{gubun}
order by 1,2,3,4,5,6,7;

choose.when:
select YYYYMM, SEL_CODE, 'VINA' SITE, 구분, ISNULL(NULLIF(LTRIM(RTRIM(도우코드)),N''),MODEL) as MODEL, EXPEN_SEL, expen_sel명 AS EXPEN_SEL명, ACCT_NAME, AVG(BOH_QTY) BOH_QTY, AVG(IN_QTY) IN_QTY, AVG(EOH_QTY) EOH_QTY, AVG(OUT_QTY) OUT_QTY, AVG(LOSS_QTY) LOSS_QTY, AVG(RMAIN_QTY) RMAIN_QTY, AVG(ADJ_QTY) ADJ_QTY, SUM(BOH) BOH, SUM([IN]) INPUT_AMT, SUM(EOH) EOH, SUM([OUT]) OUT_AMT, SUM(LOSS) LOSS, SUM(RMAIN_AMT) RMA_IN from ( ) v where 1=1
and SUB_NAME LIKE '%' + #{acctName}
GROUP BY YYYYMM,SEL_CODE,구분, ISNULL(NULLIF(LTRIM(RTRIM(도우코드)),N''),MODEL),EXPEN_SEL,expen_sel명,ACCT_NAME order BY 1 desc,2 desc,4,5,6;

choose.otherwise:
select YYYYMM, SEL_CODE, CASE WHEN SITE='HQ' then '본사' WHEN SITE='VN' then 'VINA' else SITE end SITE, 구분, ISNULL(NULLIF(LTRIM(RTRIM(도우코드)),N''),MODEL) as MODEL, EXPEN_SEL, EXPEN_SEL명, ACCT_NAME, AVG(BOH_QTY) BOH_QTY, AVG(IN_QTY) IN_QTY, AVG(EOH_QTY) EOH_QTY, AVG(OUT_QTY) OUT_QTY, AVG(LOSS_QTY) LOSS_QTY, AVG(coalesce(RMAIN_QTY,0)) RMAIN_QTY, AVG(ADJ_QTY) ADJ_QTY, SUM(BOH) BOH, SUM([IN]) INPUT_AMT, SUM(EOH) EOH, SUM([OUT]) OUT_AMT, SUM(LOSS) LOSS, SUM(coalesce(RMAIN_AMT,0)) RMA_IN from doi_cost where 1=1
and YYYYMM = #{yyyymm}
and SITE = #{site}
and SUB_NAME LIKE '%' + #{acctName}
GROUP BY YYYYMM,SEL_CODE, CASE WHEN SITE='HQ' then '본사' WHEN SITE='VN' then 'VINA' else SITE end, 구분,ISNULL(NULLIF(LTRIM(RTRIM(도우코드)),N''),MODEL),EXPEN_SEL,EXPEN_SEL명,ACCT_NAME--,ITEM_NAME order BY 1 desc,2 desc,3,4,5,6,7,8;

choose.when:
SELECT s.yyyymm AS YYYYMM, s.sel_code AS SEL_CODE, 'VINA' AS SITE, CASE WHEN MAX(NULLIF(LTRIM(RTRIM(s.division)),'')) = 'MP' THEN N'양산' WHEN MAX(NULLIF(LTRIM(RTRIM(s.division)),'')) IS NOT NULL THEN N'개발' ELSE (CASE WHEN RIGHT(s.도우코드,1)='D' THEN N'개발' ELSE N'양산' END) END AS 구분, s.도우코드 AS 도우코드, s.도우코드 AS MODEL, 'WH0006' AS STOCK, CAST(SUM(ISNULL(s.BOH,0)) AS numeric(18,2)) AS BOH, CAST(SUM(ISNULL(s.T_INPUT,0) + ISNULL(s.ETCIN_TOTAL,0)) AS numeric(18,2)) AS IN_QTY, CAST(SUM(ISNULL(s.T_OUTPUT,0) + ISNULL(s.ETCOUT_TOTAL,0) + ISNULL(s.LOSS,0)) AS numeric(18,2)) AS OUT_QTY, CAST(SUM(ISNULL(s.EOH_WH0006,0)) AS numeric(18,2)) AS EOH, 0 AS RMA_OUT FROM doi_vn_stock_resc s WHERE s.sel_code = 'ACTUAL' AND s.도우코드 IS NOT NULL AND LTRIM(RTRIM(s.도우코드)) <> '' AND s.도우코드 <> N'TOTAL'
AND s.yyyymm = #{yyyymm}
GROUP BY s.yyyymm, s.sel_code, s.도우코드 ORDER BY 구분, s.도우코드;

choose.otherwise:
select A.YYYYMM, A.SEL_CODE, CASE WHEN A.SITE='HQ' then '본사' WHEN A.SITE ='VN' then 'VINA' else A.SITE end SITE, CASE WHEN RIGHT(A.MODEL_TYPE,1)='D' THEN '개발' ELSE '양산' END as 구분, A.MODEL_TYPE as 도우코드, A.MODEL, A.STOCK, A.BOH, A.[INPUT] IN_QTY, [OUT] OUT_QTY, A.EOH, COALESCE(B.RMA_OUT,0) as RMA_OUT from doi_stock a left join doi_rma_inout b ON(A.YYYYMM=B.YYYYMM and A.SITE=B.SITE and a.MODEL_TYPE=b.도우코드) where 1=1
and a.YYYYMM = #{yyyymm}
and a.SITE = #{site}
ORDER BY 1,2,3,4,5

choose.when:
select YYYYMM, SEL_CODE, 'VINA' SITE, 구분, 도우코드 AS MODEL, EXPEN_SEL, expen_sel명 AS EXPEN_SEL명, ACCT_NAME, BOH_QTY, BOH_AMT, T_INPUT_QTY AS IN_QTY, T_INPUT_AMT AS IN_AMT, EOH_WH0006_QTY AS EOH_QTY, EOH_WH0006_AMT AS EOH_AMT, T_OUTPUT_QTY AS OUT_QTY, T_OUTPUT_AMT AS OUT_AMT from doi_vn_stco where 1=1 and sel_code = 'ACTUAL'
and YYYYMM = #{yyyymm}
and 구분 = #{gubun}
and ACCT_NAME != N'기타출고' order BY 구분, 도우코드, EXPEN_SEL;

choose.otherwise:
select YYYYMM, SEL_CODE, CASE WHEN SITE='HQ' then '본사' WHEN SITE='VN' then 'VINA' else SITE end SITE, 구분, MODEL, EXPEN_SEL, EXPEN_SEL명, ACCT_NAME, BOH AS BOH_QTY, BOH_AMT, INPUT AS IN_QTY, IN_AMT, EOH AS EOH_QTY, EOH_AMT, [OUT] AS OUT_QTY, OUT_AMT from doi_stco where 1=1 and sel_code = 'ACTUAL'
and YYYYMM = #{yyyymm}
and SITE = #{site}
and 구분 = #{gubun}
and ACCT_NAME != N'기타출고' --and BOH_AMT+IN_AMT+EOH_AMT+OUT_AMT > 0 order BY 1,2,3,4,5;

mapper.select:
select 거래명세서번호, 거래명세서일, 부서, 담당자, CASE WHEN 통화 = 'KRW' THEN '국내' ELSE '수출' END AS 구분, 거래처, 품명, 품번, 판매단위, 수량, 통화, 환율, 판매단가, CASE WHEN 통화 = 'KRW' THEN 판매금액 ELSE NULL END AS 국내공급가액, CASE WHEN 통화 = 'USD' THEN 판매금액 ELSE NULL END AS 수출판매금액, 부가세액, 원화판매금액, 원화부가세액, 원화판매금액계, 매출수량, 매출금액계, 세금계산서금액계 from doi_sale_resc where 1=1
and YYYYMM = #{yyyymm}
and SITE = #{site}
union all select Invoice관리번호, Invoice_Date, 부서, 담당자, '수출' AS 구분, Buyer, 품명, 품번, 단위, 수량, 통화, 환율, 판매단가, null AS 국내공급가액, 판매금액 AS 수출판매금액, null AS 부가세액, 원화판매금액, null AS 원화부가세액, 원화판매금액 AS 원화판매금액계, 수량 as 매출수량, 매출금액계, null AS 세금계산서금액계 from doi_invoice_resc where 1=1
and YYYYMM = #{yyyymm}
and SITE = #{site}
order by 거래처,거래명세서번호, 거래명세서일;

choose.otherwise:
select 구분, model, 면적, DIST_IN AS DIST_VALUE, dist_rate, SUB_NAME, EXPEN_SEL, EXPEN_SEL명, adj_qty, in_qty, out_qty, loss_qty, -- unit_cost, max(disp_seq) as disp_seq, sum([in]) as input_Amt from doi_expen_matl where 1=1 and sel_code='ACTUAL' and expen_sel != 'NONE'
and YYYYMM = #{yyyymm}
and SITE = #{site}
group by 구분, model, 면적, DIST_IN, dist_rate, SUB_NAME, EXPEN_SEL, EXPEN_SEL명, adj_qty, in_qty, out_qty, loss_qty order by 구분,MODEL,DISP_SEQ,EXPEN_SEL;

choose.when:

select
    b.구분,
    ISNULL(NULLIF(LTRIM(RTRIM(mc.도우코드)),''), b.model) as model,
    b.SUB_NAME, b.ITEM_NAME, b.EXPEN_SEL, b.EXPEN_SEL명,
    b.SALE_AMT, b.TOT_AMT, b.TOT_SMCE, b.TOT_ACCT, b.DIST_RATE, b.DIST_AMT
from DOI_SMCE_COST b
left join (
    select MODEL, 도우코드 from (
        select MODEL, 도우코드, row_number() over (partition by MODEL order by 도우코드) rn
        from ( select distinct MODEL, 도우코드 from DOI_VN_STCO
               where 1=1
               and YYYYMM = #{yyyymm}
               and SEL_CODE = #{selCode}
             ) d
    ) z where z.rn = 1
) mc on mc.MODEL = b.model
where 1=1

    and b.YYYYMM = #{yyyymm}


    and b.SITE = #{site}


    and b.SEL_CODE = #{selCode}

order by model, b.EXPEN_SEL, b.EXPEN_SEL명, b.구분;

choose.otherwise:
select 구분,model,SUB_NAME,ITEM_NAME,EXPEN_SEL,EXPEN_SEL명,SALE_AMT,TOT_AMT,TOT_SMCE,TOT_ACCT,DIST_RATE,DIST_AMT
from DOI_SMCE_COST
where 1=1

    and YYYYMM = #{yyyymm}


    and SITE = #{site}


    and SEL_CODE = #{selCode}

order by  model, EXPEN_SEL, EXPEN_SEL명 ,구분 ;  --SUB_NAME, ITEM_NAME,
